def polish(text):
    # Prose spacing only; identifiers and URLs in code/URL tokens are preserved.
    if text.startswith('# Проверенные первоисточники'):return text
    text,reference_heading,references=text.partition('\n## Литература')
    # Protect Markdown destinations as well as code and URLs. Captions remain
    # editable, but e.g. ](figures/residuals.png) must never be translated.
    parts=re.split(r'(\]\([^\n)]*\)|`[^`]+`|https?://\S+)',text)
    for i in range(0,len(parts),2):
        s=parts[i]
        s=re.sub(r'([А-Яа-яЁё])(\d)',r'\1 \2',s)
        s=re.sub(r'(\d)([А-Яа-яЁё])',r'\1 \2',s)
        s=re.sub(r'\b(Атырау|Актау|Актобе)\s*(32|235|22|31|33|86)\b',r'\1, пост № \2',s)
        replacements={'test-сутках':'сутках итоговой проверки','test-сутки':'сутки итоговой проверки','Независимый test 2025 года':'Отложенная проверка на данных 2025 года','Независимый test':'Отложенная проверка','Объяснительная модель':'Объяснительная модель','Train —':'Обучение —','validation —':'валидация —','test —':'итоговая проверка —','Train2022':'Обучение: 2022','Test2025':'Данные проверки за 2025 год','train+validation':'обучающая и валидационная части','preregistered':'заранее зафиксированный','exploratory-анализ':'исследовательский анализ','является exploratory':'является дополнительным исследовательским','offline-эксперимент':'ретроспективный эксперимент','offline origin':'момент выпуска в ретроспективной проверке','operational-доступности':'оперативной доступности','operationalforecast':'оперативного прогноза','upstream':'первичного поставщика','timestamps поступления':'временные метки поступления','refit':'повторное обучение','missing target':'пропущенные целевые значения','target остаётся missing':'целевая величина остаётся пропущенной','предикты':'предсказания','Предикты':'Предсказания','residuals':'остатки','WHO':'ВОЗ'}
        for a,b in replacements.items():s=s.replace(a,b)
        for a,b in {'сутках test':'сутках итоговой проверки','повторное обучение обучающая и валидационная части':'повторное обучение на обучающей и валидационной частях','MAE validation':'MAE на валидации','метрики test':'метрики итоговой проверки','внутри train':'только на обучающей части','на test':'на итоговой проверке','по validation':'по валидации','По validation':'По валидации','baseline mean':'среднее обучающего периода','обязательным baseline':'обязательным контрольным ориентиром','station_id32':'идентификатор поста — 32','станций № 32, 22 и 31':'станций № 32, 22 и 31','Таблица5.':'Таблица 5.','ID235':'ID 235','ID32':'ID 32','канале235':'канале 235','по32':'по посту 32','на235':'на посту 235','от32':'от поста 32','проблемы32':'проблемы поста 32','по235':'по посту 235','ряды33':'ряды 33','makes235':'делает 235'}.items():s=s.replace(a,b)
        s=s.replace('станция47.','станция: 47.').replace('станции 47.','станции: 47.').replace('таблицы results','таблицы результатов')
        s=s.replace('Станция Атырау, пост № 32 обозначена','Пост № 32 в Атырау обозначен').replace('На Атырау, пост № 32','На посту № 32 в Атырау').replace('На Актобе, пост № 31','На посту № 31 в Актобе')
        s=s.replace('средняя опубликованная PM2.5 станции Атырау, пост № 32','средняя опубликованная PM2.5 на посту № 32 в Атырау')
        s=s.replace('## 6. Основной результат test','## 6. Результат отложенной проверки')
        s=s.replace('По валидации выбран среднее обучающего периода','По валидации выбрано среднее обучающего периода')
        parts[i]=s
    return ''.join(parts)+reference_heading+references

def improve(text,number,here,case2):
    from build_content import table
