    q235=qc[(qc.city=='Atyrau')&(qc.station_id==235)].iloc[0]
    comp=pd.read_csv(here/'results/completeness_sensitivity.csv')
    boot=pd.read_csv(case2/'results/paired_error_block_sensitivity.csv')
